#include <stdint.h>
#include <stdbool.h>

/* ------------------------------------------------------------------
 * 1) 寄存器与位定义（示意）
 *    真实地址与全部位域一律以你所用手册为准：
 *    - Reference Manual：GPIOx_MODER / OTYPER / PUPDR / IDR / ODR / BSRR
 *    - Datasheet：引脚复用映射表、单脚与全芯片电流上限
 * ------------------------------------------------------------------ */
typedef struct {
    volatile uint32_t MODER;   /* 模式：输入 / 输出 / 复用 / 模拟 */
    volatile uint32_t OTYPER;  /* 输出类型：0 = 推挽，1 = 开漏 */
    volatile uint32_t OSPEEDR; /* 输出速度（翻转速率） */
    volatile uint32_t PUPDR;   /* 上拉 / 下拉 */
    volatile uint32_t IDR;     /* 输入数据寄存器（只读） */
    volatile uint32_t ODR;     /* 输出数据寄存器 */
    volatile uint32_t BSRR;    /* 位设置 / 复位寄存器（原子写，不必读改写） */
} GPIO_TypeDef;

#define GPIOA_BASE   (0x48000000UL)             /* 示意地址 */
#define GPIOA        ((GPIO_TypeDef *)GPIOA_BASE)

#define PIN5         (5U)
#define PIN_MASK(p)  (1UL << (p))

/* MODER 每个引脚占 2 bit */
#define MODE_INPUT   0x0U
#define MODE_OUTPUT  0x1U
#define MODE_AF      0x2U
#define MODE_ANALOG  0x3U

/* OTYPER 每个引脚占 1 bit */
#define OTYPER_PP    0x0U   /* 推挽 Push-Pull */
#define OTYPER_OD    0x1U   /* 开漏 Open-Drain */

/* PUPDR 每个引脚占 2 bit */
#define PULL_NONE    0x0U
#define PULL_UP      0x1U
#define PULL_DOWN    0x2U

typedef struct {
    uint8_t  pin;
    uint8_t  mode;      /* MODE_INPUT / MODE_OUTPUT / MODE_AF / MODE_ANALOG */
    uint8_t  otype;     /* OTYPER_PP / OTYPER_OD */
    uint8_t  pull;      /* PULL_NONE / PULL_UP / PULL_DOWN */
    uint32_t af;        /* 复用功能编号，仅 mode = MODE_AF 时有效 */
} GpioConfig;

/* ------------------------------------------------------------------
 * 2) 初始化：把一个引脚配置成目标模式
 *    只修改目标位，其余位保持原值，避免影响同一端口上的其他引脚。
 * ------------------------------------------------------------------ */
void gpio_init(GPIO_TypeDef *port, const GpioConfig *cfg)
{
    if ((port == 0) || (cfg == 0) || (cfg->pin > 15U)) {
        return;   /* 参数自检：启动阶段就拦住错误配置 */
    }

    const uint32_t pos    = (uint32_t)cfg->pin * 2U;      /* MODER / PUPDR 的位偏移 */
    const uint32_t twoBit = 0x3UL << pos;
    const uint32_t oneBit = 1UL << (uint32_t)cfg->pin;

    /* 必须先清掉旧的复用配置，再写入新值 */
    port->MODER = (port->MODER & ~twoBit) | ((uint32_t)cfg->mode << pos);

    /* 输出类型：仅输出 / 复用模式有意义 */
    port->OTYPER = (port->OTYPER & ~oneBit) | ((uint32_t)cfg->otype << (uint32_t)cfg->pin);

    /* 上拉 / 下拉：输入模式用来避免悬空，输出模式通常保持 PULL_NONE */
    port->PUPDR = (port->PUPDR & ~twoBit) | ((uint32_t)cfg->pull << pos);

    if (cfg->mode == MODE_AF) {
        /* 复用功能编号通常由 AFRL / AFRH 两个寄存器各管 8 个引脚，
           这里仅示意需要按引脚序号选择寄存器并写入 4 bit 编号 */
        /* gpio_set_af(port, cfg->pin, cfg->af); */
    }
}

/* ------------------------------------------------------------------
 * 3) 位操作：只动目标引脚，绝不整端口赋值
 *    （整端口赋值会把同端口其他引脚的状态一起冲掉）
 * ------------------------------------------------------------------ */
static inline void gpio_set(GPIO_TypeDef *port, uint8_t pin)
{
    port->BSRR = PIN_MASK(pin);            /* 置 1：不建议用 ODR |= mask，读改写非原子 */
}

static inline void gpio_reset(GPIO_TypeDef *port, uint8_t pin)
{
    port->BSRR = (uint32_t)PIN_MASK(pin) << 16U;   /* 高位半字用于复位 */
}

static inline void gpio_toggle(GPIO_TypeDef *port, uint8_t pin)
{
    port->ODR ^= PIN_MASK(pin);            /* 单主控场景可用，多上下文需注意原子性 */
}

static inline bool gpio_read(GPIO_TypeDef *port, uint8_t pin)
{
    return (port->IDR & PIN_MASK(pin)) != 0UL;
}

/* ------------------------------------------------------------------
 * 4) 使用示例：推挽输出点灯 + 上拉输入读按键
 * ------------------------------------------------------------------ */
#define LED_PIN     PIN5
#define BUTTON_PIN  (3U)

static void led_init(void)
{
    const GpioConfig led = { LED_PIN, MODE_OUTPUT, OTYPER_PP, PULL_NONE, 0U };
    gpio_init(GPIOA, &led);
}

static void button_init(void)
{
    /* 上拉输入：按键另一端接 GND，松开读 1、按下读 0，不会悬空 */
    const GpioConfig key = { BUTTON_PIN, MODE_INPUT, OTYPER_PP, PULL_UP, 0U };
    gpio_init(GPIOA, &key);
}

int main(void)
{
    led_init();
    button_init();

    uint32_t press_count = 0U;
    bool     last_level   = true;   /* 上拉输入：松开状态为高电平 */

    for (;;) {
        /* 简单软件延时只用于教学；真实项目应改用定时器 */
        for (volatile uint32_t i = 0U; i < 200000U; i++) {
        }

        gpio_toggle(GPIOA, LED_PIN);

        const bool level = gpio_read(GPIOA, BUTTON_PIN);
        if (last_level && !level) {
            press_count++;      /* 下降沿：按键被按下 */
        }
        last_level = level;
    }
}
